// Sequências decorativas. O relógio real continua no motor, sem espera.
const MARE=[0,54,108,166,224,278,330,386,444,504];
export const IMPACTO_DO_BOTE_DA_GARCA_MS = 114;
const GARCA=[0,39,78,IMPACTO_DO_BOTE_DA_GARCA_MS,142,176,212,247,284,322,368];
export const DURACAO_DO_BOTE_DA_GARCA=GARCA.at(-1);
// Ponto do corpo em relação à casa, poses agrupadas de asa/pescoço.
const VOOS=[
 [46,-43,3],[35,-30,3],[21,-16,3],[4,-1,3],[-1,0,3],
 [-13,-5,5],[-26,-14,4],[-39,-25,0],[-54,-35,4],[-71,-45,5],
];
const empurraoDaMare=[[0,0,0],[0,0,0],[1,0,0],[3,1,0],[6,2,4],[9,3,10],[12,4,19]];
// Sete centros equidistantes, do impacto ao marco de retorno do motor.
const RECUO_GARCA=[IMPACTO_DO_BOTE_DA_GARCA_MS,131.5,149,166.5,184,201.5,219];
const FREIO_GARCA=[219,244,270,296];
const distancia=(a,b)=>Math.abs(a.coluna-b.coluna)+Math.abs(a.linha-b.linha);
const caminhoDaGarca=casa=>casa.apoioExposto===true&&casa.apoioRetorno===true&&distancia(casa,casa.retorno)===1;
const fase=(tempos,t)=>tempos.findLastIndex(x=>x<=t);
const pixel=(ctx,cor,x,y,w,h)=>{ctx.fillStyle=cor;ctx.fillRect(x,y,w,h);};

export function quadroDosPerigos(emCurso,t) {
 if(!emCurso || t<0)return [];
 return emCurso.casas.map(casa=>{
  if(!casa)return;
  const tempos=casa.tipo==='mare'?MARE:GARCA, quadro=fase(tempos,t);
  if(quadro<0||quadro===tempos.length-1)return;
  if(casa.tipo!=='garca')return {...casa,quadro,ate:tempos[quadro+1]};
  const caminho=caminhoDaGarca(casa);
  const recuo=Math.max(0,fase(RECUO_GARCA,t));
  const freio=fase(FREIO_GARCA,t);
  const proxima=quadros=>quadros.find(x=>x>t)??Infinity;
  return {...casa,quadro,tempo:t,caminho,recuo,freio,
    ate: caminho ? Math.min(tempos[quadro+1],proxima(RECUO_GARCA),proxima(FREIO_GARCA))
      : Math.min(tempos[quadro+1],proxima([126,146,188,219])),
  };
 });
}

export function poseDoSiriEmPerigo(perigo) {
 if(!perigo)return;
 if(perigo.tipo==='garca'){
  const t=perigo.tempo;
  const dx=(perigo.coluna-perigo.retorno.coluna)*48,dy=(perigo.linha-perigo.retorno.linha)*48;
  if(perigo.caminho){
   const falta=6-perigo.recuo;
   return {dx:dx*falta/6,dy:dy*falta/6,oculto:0};
  }
  // Sem corredor arenoso contíguo, não cruza o mar: cai de cena,
  // reaparece só dentro do marco firme que o motor já escolheu.
  if(perigo.apoioExposto!==true)return {dx:0,dy:0,oculto:0};
  if(t<114)return {dx,dy,oculto:0};
  if(t<126)return {dx,dy,oculto:5};
  if(t<146)return {dx,dy,oculto:14};
  if(t<188)return {dx:0,dy:0,oculto:23};
  if(t<219)return {dx:0,dy:0,oculto:8};
  return {dx:0,dy:0,oculto:0};
 }
 const dx=(perigo.coluna-perigo.retorno.coluna)*48;
 const dy=(perigo.linha-perigo.retorno.linha)*48;
 const i=perigo.quadro, mare=perigo.tipo==='mare';
 const pose=empurraoDaMare[i];
 if(pose)return {dx:dx+pose[0],dy:dy+pose[1],oculto:pose[2]};
 if(mare)return i===7?{dx,dy:dy+7,oculto:23}:{dx:0,dy:0,oculto:5};
 return i===8?{dx:0,dy:0,oculto:9}:{dx:0,dy:0,oculto:0};
}

const FUNDO='#377e85', RASO='#52929a', AZUL='#80bbba', ESPUMA='#dcefe1', CLARA='#eff7e9';
const FRENTES=[
 [-19,2,4],[-16,5,7],[-11,9,11],[-5,12,15],[1,14,17],[7,11,14],[13,8,10],[16,5,6],[19,3,3],
];

function pintarSurto(ctx,x,y,i){
 const [b,meia,comp]=FRENTES[i];
 // Frente crescente de maré, com três degraus e recuo. Tudo fica na
 // casa atingida, sem redesenhar linhas ou ameaçar as casas vizinhas.
 function trecho(cor,u,v,l,a=1){
  const u0=Math.max(-24,u),u1=Math.min(24,u+l),v0=Math.max(-24,v),v1=Math.min(24,v+a);
  if(u1>u0&&v1>v0)pixel(ctx,cor,x+u0,y+v0,u1-u0,v1-v0);
 }
 for(let row=-meia;row<=meia;row++){
   const nivel=Math.abs(row)*4/Math.max(1,meia)|0;
   const frente=b+5-nivel;
   const arrasto=comp-((nivel+1)>>1);
   trecho(FUNDO,frente-arrasto,row,arrasto);
   if(nivel<4)trecho(RASO,frente-Math.max(4,arrasto-3),row,Math.max(4,arrasto-3));
   trecho(AZUL,frente-3,row,4);
   if(nivel<4)trecho(row<-meia/3?CLARA:ESPUMA,frente-1,row,2);
 }
 if(i>=2&&i<=6){
   trecho(ESPUMA,b+4,-meia-2,4,2);
   trecho(AZUL,b+1,-meia-5,2,2);
   trecho(ESPUMA,b+6,meia+2,3);
   if(i===4)trecho(AZUL,b-7,meia-2,3,2);
 }
}

