function pintarGarca(ctx,x,y,pose){
 for(const [t,dx,dy,w] of CORRIDA_GARCA[pose])pixel(ctx,TINTAS_GARCA[t],x+dx,y+dy,w,1);
}
// No contato com a areia do marco, os grãos viajam no sentido oposto.
const GRAOS_FREIO=[
 [-5,10,2,'#dfbd88'],[-2,14,1,'#ead2a4'],[1,11,2,'#ba8c5f'],
 [-6,9,1,'#efdbab'],[4,7,2,'#c49a6c'],[7,7,1,'#f1d3a0'],
];
function pintarFreioDaGarca(ctx,origem,e) {
 if(!e.caminho||e.freio<0||e.freio>2)return;
 const x=origem.origemX+48*e.retorno.coluna+24,y=origem.origemY+48*e.retorno.linha+24;
 const t=[.19,.53,.88][e.freio];
 const eixoX=Math.sign(e.coluna-e.retorno.coluna),eixoY=Math.sign(e.linha-e.retorno.linha);
 for(const [inicio,alcance,l,cor] of GRAOS_FREIO){
  const curso=Math.round(4+alcance*t);
  const dy=Math.round(-4*(3+alcance%6)*t*(1-t));
  // Pixels sempre ficam dentro da área útil da mesma casa.
  const gx=Math.max(-19,Math.min(18,eixoX*curso+(eixoY?inicio:0)));
  const gy=Math.max(-17,Math.min(17,9+eixoY*curso+dy+(eixoX?(inicio%3):0)));
  pixel(ctx,cor,x+gx,y+gy,l,1);
 }
}

export function pintarPerigos(ctx,origem,quadro) {
 if(!quadro.some(Boolean))return;
 ctx.save();ctx.setTransform(1,0,0,1,0,0);
 const garcas=new Set();
 for(const e of quadro){
  if(!e)continue;
  const x=origem.origemX+48*e.coluna+24,y=origem.origemY+48*e.linha+24;
  if(e.tipo==='mare'){pintarSurto(ctx,x,y,e.quadro);continue;}
  const chave=e.coluna+':'+e.linha;
  if(garcas.has(chave))continue;
  garcas.add(chave);
  const [dx,dy,pose]=VOOS[e.quadro];
  pintarFreioDaGarca(ctx,origem,e);
  pintarGarca(ctx,x+dx,y+dy,pose);
 }
 ctx.restore();
}
